import java.util.*;
public class CF933C {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Circle> circleList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            int r = scanner.nextInt();
            circleList.add(new Circle(x, y, r));
        }
        if (n == 3 && !Circle.isIntersect(circleList.get(0), circleList.get(1))) {
            int sum = 4;
            if (Circle.isIntersect2(circleList.get(0), circleList.get(2))) sum++;
            if (Circle.isIntersect2(circleList.get(1), circleList.get(2))) sum++;
            System.out.println(sum);
            return;
        }
        int totalCount = 1;
        TreeSet<Point> pointsSet = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            pointsSet.clear();
            totalCount++;
            for (int j = 0; j < i; j++) {
                Circle.intersectAt(circleList.get(i), circleList.get(j), pointsSet);
            }
            if (pointsSet.size() >= 2) {
                totalCount += pointsSet.size() - 1;
            }
        }
        System.out.println(totalCount);
        scanner.close();
    }

    public static double distance(Point a, Point b) {
        return Math.hypot(a.x - b.x, a.y - b.y);
    }

    static class Circle {
        Point center;
        int r;
        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.r = r;
        }
        public static boolean isIntersect(Circle a, Circle b) {
            double d = distance(a.center, b.center);
            return d <= a.r + b.r + 1e-10 && d + 1e-10 >= Math.abs(a.r - b.r);
        }
        public static boolean isIntersect2(Circle a, Circle b) {
            double d = distance(a.center, b.center);
            return d < a.r + b.r && d > Math.abs(a.r - b.r);
        }
        public static void intersectAt(Circle a, Circle b, Set<Point> set) {
            if (!isIntersect(a, b)) return;
            Line line = new Line(a.center, b.center);
            double d = distance(a.center, b.center);
            double midDist = (d * d - b.r * b.r + a.r * a.r) / (2 * d);
            Point mid = a.center.moveAlongLine(line, midDist);
            Point alpha = line.asVector().getAlpha();
            double height = Math.sqrt(a.r * a.r - midDist * midDist);
            Point p1 = mid.moveAlongVector(alpha, height);
            Point p2 = mid.moveAlongVector(alpha, -height);
            set.add(p1);
            if (!p2.equals(p1)) set.add(p2);
        }
    }

    static class Point implements Comparable<Point> {
        double x, y;
        public Point(double x, double y) { this.x = x; this.y = y; }
        public Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        public Point moveAlongLine(Line l, double len) {
            return moveAlongVector(l.asVector(), len);
        }
        public Point moveAlongVector(Point v, double len) {
            double mag = Math.hypot(v.x, v.y);
            if (mag < 1e-15) return new Point(x, y);
            return add(new Point(v.x / mag, v.y / mag).mul(len));
        }
        public Point add(Point o) { return new Point(x + o.x, y + o.y); }
        public Point mul(double f) { return new Point(x * f, y * f); }
        public Point getAlpha() { return new Point(-y, x); }
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return Math.abs(x - p.x) < 1e-10 && Math.abs(y - p.y) < 1e-10;
        }
        @Override
        public int compareTo(Point o) {
            if (equals(o)) return 0;
            if (Math.abs(x - o.x) < 1e-10) return Double.compare(y, o.y);
            return Double.compare(x, o.x);
        }
    }

    static class Line {
        Point from, to;
        public Line(Point from, Point to) { this.from = from; this.to = to; }
        public Point asVector() { return to.sub(from); }
        public double length() { return Math.hypot(to.x - from.x, to.y - from.y); }
    }
