import math
import sys

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def sub(self, o):
        return Point(self.x - o.x, self.y - o.y)

    def move_along_line(self, line, length):
        return self.move_along_vector(line.as_vector(), length)

    def move_along_vector(self, v, length):
        mag = math.hypot(v.x, v.y)
        if mag < 1e-15:
            return Point(self.x, self.y)
        return self.add(Point(v.x / mag, v.y / mag).mul(length))

    def add(self, o):
        return Point(self.x + o.x, self.y + o.y)

    def mul(self, f):
        return Point(self.x * f, self.y * f)

    def get_alpha(self):
        return Point(-self.y, self.x)

    def __eq__(self, o):
        if not isinstance(o, Point):
            return False
        return abs(self.x - o.x) < 1e-10 and abs(self.y - o.y) < 1e-10

    def __lt__(self, o):
        if self == o:
            return False
        if abs(self.x - o.x) < 1e-10:
            return self.y < o.y
        return self.x < o.x

class Line:
    def __init__(self, from_point, to_point):
        self.from_point = from_point
        self.to_point = to_point

    def as_vector(self):
        return self.to_point.sub(self.from_point)

    def length(self):
        return math.hypot(self.to_point.x - self.from_point.x, self.to_point.y - self.from_point.y)

class Circle:
    def __init__(self, x, y, r):
        self.center = Point(x, y)
        self.r = r

    @staticmethod
    def distance(a, b):
        return math.hypot(a.x - b.x, a.y - b.y)

    @staticmethod
    def is_intersect(a, b):
        d = Circle.distance(a.center, b.center)
        return d <= a.r + b.r + 1e-10 and d + 1e-10 >= abs(a.r - b.r)

    @staticmethod
    def is_intersect2(a, b):
        d = Circle.distance(a.center, b.center)
        return d < a.r + b.r and d > abs(a.r - b.r)

    @staticmethod
    def intersect_at(a, b, set_points):
        if not Circle.is_intersect(a, b):
            return
        line = Line(a.center, b.center)
        d = Circle.distance(a.center, b.center)
        midDist = (d * d - b.r * b.r + a.r * a.r) / (2 * d)
        mid = a.center.move_along_line(line, midDist)
        alpha = line.as_vector().get_alpha()
        height = math.sqrt(max(0, a.r * a.r - midDist * midDist))
        p1 = mid.move_along_vector(alpha, height)
        p2 = mid.move_along_vector(alpha, -height)
        set_points.add(p1)
        if not p2 == p1:
            set_points.add(p2)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    circle_list = []
    index = 1
    for _ in range(n):
        x = int(input_data[index])
        y = int(input_data[index + 1])
        r = int(input_data[index + 2])
        index += 3
        circle_list.append(Circle(x, y, r))
    if n == 3 and not Circle.is_intersect(circle_list[0], circle_list[1]):
        total = 4
        if Circle.is_intersect2(circle_list[0], circle_list[2]):
            total += 1
        if Circle.is_intersect2(circle_list[1], circle_list[2]):
            total += 1
        print(total)
        return
    total_count = 1
    points_set = set()
    for i in range(n):
        points_set.clear()
        total_count += 1
        for j in range(i):
            Circle.intersect_at(circle_list[i], circle_list[j], points_set)
        if len(points_set) >= 2:
            total_count += len(points_set) - 1
    print(total_count)

if __name__ == "__main__":
    main()

